public sealed class FileCache
{
    private readonly Lock _strategy;   // .NET 9/C# 13; Monitor or ReaderWriterLockSlim otherwise
    public FileCache(Lock strategy) => _strategy = strategy;

    public string? Find(string path)
    {
        lock (_strategy)                 // Lock.EnterScope() + Dispose on scope exit
            return FindCore(path);       // assumes the lock is held
    }
}
